(()=>{const csrf='<?=DailyStudio::esc((string)($_SESSION['verse_generator_csrf']??''))?>';const requestVoices=async()=>{const r=await fetch('/beyond-id/admin/api/elevenlabs-test.php',{method:'POST',headers:{'X-CSRF-Token':csrf}});const d=await r.json();if(!r.ok)throw new Error(d.error||'Connection failed.');return d;};const b=document.getElementById('testElevenLabs'),s=document.getElementById('elevenTestStatus');if(b)b.addEventListener('click',async()=>{b.disabled=true;s.textContent='Testing…';try{const d=await requestVoices();s.textContent=d.message+' This checks your account only; it does not generate audio.';}catch(e){s.textContent=e.message||'Connection failed.';}finally{b.disabled=false;}});const load=document.getElementById('loadElevenLabsVoices'),listStatus=document.getElementById('elevenVoiceListStatus'),list=document.getElementById('elevenLabsVoiceOptions');if(load)load.addEventListener('click',async()=>{load.disabled=true;listStatus.textContent='Loading…';try{const d=await requestVoices();list.replaceChildren(...(d.voices||[]).map(v=>{const option=document.createElement('option');option.value=v.id;option.label=v.name+' · '+v.id;return option;}));listStatus.textContent=(d.voices||[]).length+' voices available. Type a voice name or ID to find it.';}catch(e){listStatus.textContent=e.message||'Could not load voices.';}finally{load.disabled=false;}});const chars=[...document.querySelectorAll('[data-character]')],warning=document.getElementById('characterVoiceWarning');const checkShared=()=>{const values=chars.map(el=>el.value.trim()).filter(Boolean);const same=new Set(values).size<values.length;if(warning){warning.style.display=same?'block':'none';if(same)warning.textContent='Two character profiles share one voice ID. Assign distinct voices to Louis, Pablo, Irie, and Jazzy.';}};chars.forEach(input=>input.addEventListener('input',checkShared));checkShared();})();
</script>
